#include <iostream>
#include <string>

std::string read_line() {
    std::string line;
    std::getline(std::cin, line);
    return line;
}

bool solve(const std::string& tag, const std::string& pat) {
    auto tag_it = tag.begin();

    for (char pat_chr : pat) {
        while (true) {
            if (tag_it == tag.end()) {
                return false;
            }
            char tag_chr = *tag_it++;
            if (tag_chr == pat_chr) {
                break;
            }
        }
    }
    return true;
}

int main() {
    std::string input = read_line();
    // trim
    size_t start = input.find_first_not_of(" \t\n\r\f\v");
    size_t end = input.find_last_not_of(" \t\n\r\f\v");
    std::string trimmed = (start == std::string::npos) ? "" : input.substr(start, end - start + 1);

    if (solve(trimmed, "hello")) {
        std::cout << "YES\n";
    } else {
        std::cout << "NO\n";
    }
    return 0;
}

